package com.huy.enterprise.inventory; import com.huy.enterprise.common.enums.RecordStatus; import jakarta.validation.constraints.*; import java.math.BigDecimal; import java.util.UUID; record WarehouseRequest(@NotBlank String warehouseCode,@NotBlank String name,String address,RecordStatus status){} record WarehouseResponse(UUID id,String warehouseCode,String name,String address,RecordStatus status){static WarehouseResponse from(Warehouse w){return new WarehouseResponse(w.getId(),w.getWarehouseCode(),w.getName(),w.getAddress(),w.getStatus());}} record InventoryRequest(@NotNull UUID warehouseId,@NotNull UUID productId,@NotNull @PositiveOrZero BigDecimal quantity,@NotNull @PositiveOrZero BigDecimal lowStockThreshold){} record InventoryResponse(UUID id,UUID warehouseId,String warehouseName,UUID productId,String productName,BigDecimal quantity,BigDecimal lowStockThreshold){static InventoryResponse from(InventoryItem i){return new InventoryResponse(i.getId(),i.getWarehouse().getId(),i.getWarehouse().getName(),i.getProduct().getId(),i.getProduct().getName(),i.getQuantity(),i.getLowStockThreshold());}}
